components.css:
.person-name { font-size: 1.75rem; line-height: 1.2; letter-spacing: -.025em; }
.person-subtitle { margin-top: .375rem; font-size: .875rem; }
.person-name { color: var(--color-primary); text-decoration: underline; }
.person-identity { display: inline-flex; align-items: center; gap: .75rem; min-width: 0; }
.person-avatar { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; width: 2.75rem; height: 2.75rem; border: 1px solid var(--color-private-line); border-radius: 50%; background: var(--color-surface); color: var(--color-primary); font-size: .875rem; font-weight: 600; }
.person-identity-large .person-avatar { width: 4rem; height: 4rem; font-size: 1.25rem; }
.person-identity-text { display: flex; flex-direction: column; gap: .125rem; min-width: 0; }
.person-name { font-size: .9375rem; font-weight: 600; line-height: 1.4; overflow-wrap: anywhere; }
.person-subtitle { color: var(--color-quiet-note); font-size: .8125rem; line-height: 1.4; }

.app-navigation { display: flex; flex-direction: column; gap: 1.5rem; }
.app-nav-link { display: flex; gap: .75rem; align-items: center; min-height: 2.75rem; padding: .625rem .75rem; border-radius: .5rem; color: var(--color-quiet-note); font-size: .875rem; font-weight: 500; line-height: 1.4; text-decoration: none; }
.app-nav-link:hover { background: var(--color-canvas); color: var(--color-ink); }
.app-nav-link-current { background: var(--color-primary); color: var(--color-canvas); font-weight: 600; }
.app-nav-link-current:hover { background: var(--color-primary-hover); color: var(--color-canvas); }
.app-navigation { margin-top: 2rem; }

.date-marker { width: 3.25rem; flex-shrink: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: .125rem; padding: .5rem .25rem; border: 1px solid var(--color-private-line); border-radius: .625rem; color: var(--color-primary); background: var(--color-surface); line-height: 1; }
.date-marker-month { font-size: .75rem; font-weight: 500; }
.date-marker-day { font-size: 1.375rem; font-weight: 600; }

.workspace-action { margin-top: auto; }
.workspace-actions { display: flex; flex-wrap: wrap; gap: .625rem; align-items: center; }
.workspace-action { display: inline-flex; min-height: 2.75rem; max-width: 100%; align-items: center; justify-content: center; gap: .5rem; padding: .625rem 1rem; border: 1px solid transparent; border-radius: .5rem; font-size: .875rem; line-height: 1.4; font-weight: 600; cursor: pointer; text-align: center; }
.workspace-action-primary { background: var(--color-primary); color: var(--color-canvas); }
.workspace-action-primary:hover { background: var(--color-primary-hover); }
.workspace-action-secondary { background: var(--color-canvas); border-color: var(--color-private-line); color: var(--color-primary); }
.workspace-action-secondary:hover { background: var(--color-surface); border-color: var(--color-primary); }
.workspace-action-quiet { color: var(--color-primary); padding-inline: .5rem; }
.workspace-action-quiet:hover { background: var(--color-surface); }
.workspace-action { margin-top: .75rem; }
.workspace-action { justify-content: flex-start; text-align: left; }
